from fractions import Fraction
from Crypto.Util.number import *

def rational_to_contfrac(x, y):
    p=x
    q=y
    ans=[]
    while q:
        ans.append(p//q)
        p,q=q,p%q
    return ans
def Convergence_function(continued):
    res =[]
    for i in range(1,len(continued)+1):
        tmp = 1
        conver = continued[:i][::-1]
        tmp = Fraction(conver[0])
        for j in conver[1:]:
            tmp = j + 1/tmp
        res.append(tmp)
    return res





result=(rational_to_contfrac(e,n))

#计算渐进分数
res=Convergence_function(result)

#筛选出d，并计算出明文
for i in res:
    try:
        x=(e*i.denominator-1)%i.numerator
        if x==0:
            d=i.denominator
            phi=(e*d-1)//i.numerator
            print(d,phi)
    except:
        continue



